<?php
namespace Tests\Feature;
use App\Models\Instansi; use App\Models\KategoriInstansi; use App\Models\Pembinaan; use App\Models\PembinaanFile; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SeparateCatalogFeatureTest extends TestCase {
 use RefreshDatabase;
 private function file(User $owner,string $name,string $jenis,string $service='Service',string $status='Tahap Persiapan',string $visibility='Private'): array { $cat=KategoriInstansi::create(['nama'=>$name.' Cat','status_aktif'=>true]); $inst=Instansi::create(['kategori_instansi_id'=>$cat->id,'nama'=>$name.' Inst','status_aktif'=>true]); $p=Pembinaan::create(['instansi_id'=>$inst->id,'created_by'=>$owner->id,'tanggal_mulai'=>'2026-10-01','metode_pelaksanaan'=>'Daring','layanan'=>$service,'status_dokumen'=>$status]); $f=PembinaanFile::create(['pembinaan_id'=>$p->id,'uploaded_by'=>$owner->id,'jenis'=>$jenis,'nama_asli'=>$name.'.pdf','path'=>'private/'.$name,'mime_type'=>'application/pdf','ukuran'=>100,'visibilitas'=>$visibility]); return [$inst,$p,$f]; }
 public function test_material_catalog_scopes_type_filters_and_download(): void { $u=User::factory()->role('pelaksana')->create(); [$inst,,$materi]=$this->file($u,'Material','materi','Needle'); [,,$laporan]=$this->file($u,'Report','laporan','Other','Selesai','Publikasi'); $this->actingAs($u)->get('/katalog-materi?q=Material&jenis=materi&visibilitas=Private&instansi_id='.$inst->id)->assertOk()->assertSee('Material.pdf')->assertDontSee('Report.pdf')->assertSee(route('pembinaan.files.download',$materi)); $this->get('/katalog-materi?q=NoResult')->assertSee('Belum ada materi yang sesuai.'); }
 public function test_report_catalog_filters_status_and_type(): void { $u=User::factory()->role('admin')->create(); [,,$report]=$this->file($u,'Report','laporan','Report Service','Selesai'); [,,$materi]=$this->file($u,'Material','materi','Material Service'); $this->actingAs($u)->get('/katalog-laporan?status_dokumen=Selesai')->assertOk()->assertSee('Report.pdf')->assertDontSee('Material.pdf')->assertSee('Selesai')->assertSee(route('pembinaan.files.download',$report)); }
 public function test_roles_guest_monitoring_and_ownership_are_enforced(): void { $owner=User::factory()->role('pelaksana')->create(); $other=User::factory()->role('pelaksana')->create(); [,,$mine]=$this->file($owner,'Mine','materi'); [,,$foreign]=$this->file($other,'Foreign','materi'); $this->get('/katalog-materi')->assertRedirect('/login'); $this->actingAs($owner)->get('/katalog-materi?q=Foreign')->assertSee('Belum ada materi yang sesuai.')->assertDontSee('Foreign.pdf'); $this->actingAs(User::factory()->role('monitoring')->create())->get('/katalog-materi')->assertOk()->assertDontSee('Upload')->assertSee('Mine.pdf')->assertSee('Foreign.pdf'); $this->actingAs($owner)->get(route('pembinaan.files.download',$foreign))->assertForbidden(); }
 public function test_report_empty_state_is_visible(): void { $u=User::factory()->role('pelaksana')->create(); $this->actingAs($u)->get('/katalog-laporan')->assertOk()->assertSee('Belum ada laporan yang sesuai.'); }
}